DROP TABLE IF EXISTS `m_date_override`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `m_date_override` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `merchant_id` bigint unsigned NOT NULL,
  `biz_date` date NOT NULL COMMENT '生效日期',
  `override_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'CLOSED 临时歇业/HOURS 改时段',
  `open_time` time DEFAULT NULL COMMENT '覆盖后的开始时间,override_type 为 HOURS 时生效',
  `close_time` time DEFAULT NULL COMMENT '覆盖后的结束时间',
  `reason` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '调整原因',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_m_date_override` (`merchant_id`,`biz_date`),
  CONSTRAINT `fk_m_override_merchant` FOREIGN KEY (`merchant_id`) REFERENCES `m_merchant` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='临时营业调整';
/*!40101 SET character_set_client = @saved_cs_client */;

