--
-- Table structure for table `m_merchant`
--

DROP TABLE IF EXISTS `m_merchant`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `m_merchant` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `pickup_point_id` bigint unsigned DEFAULT NULL COMMENT '所属自提点,空表示仅配送',
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '档口名称',
  `category_code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'OTHER' COMMENT 'RICE/NOODLE/SNACK/DRINK/FRUIT/OTHER',
  `logo_url` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'logo',
  `banner_url` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '头图',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '简介',
  `contact_name` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '联系人',
  `contact_phone` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '联系电话',
  `license_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '食品经营许可证号',
  `license_url` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '证照照片',
  `settle_account` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '结算收款标识',
  `min_order_amount` int unsigned NOT NULL DEFAULT '0' COMMENT '起购金额分',
  `pack_fee` int unsigned NOT NULL DEFAULT '0' COMMENT '默认打包费分',
  `avg_prepare_minutes` smallint NOT NULL DEFAULT '10' COMMENT '预计出餐分钟',
  `month_sold_base` int unsigned NOT NULL DEFAULT '0' COMMENT '月售基数',
  `rating_score` smallint unsigned NOT NULL DEFAULT '500' COMMENT '评分 x100',
  `rating_count` int unsigned NOT NULL DEFAULT '0' COMMENT '评价数',
  `sort_weight` int NOT NULL DEFAULT '0' COMMENT '置顶权重',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0 待审 1 营业 2 打烊 3 封禁 4 驳回',
