--
-- Table structure for table `o_refund`
--

DROP TABLE IF EXISTS `o_refund`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `o_refund` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `refund_no` char(24) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '退款单号,兼渠道幂等号',
  `order_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned NOT NULL COMMENT '冗余自订单,免 JOIN 查用户退款列表',
  `merchant_id` bigint unsigned NOT NULL COMMENT '冗余自订单,商家侧退款待办按此过滤',
  `refund_amount` int unsigned NOT NULL COMMENT '本次退款分',
  `reason_code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'OTHER' COMMENT 'TOO_SLOW/WRONG_FOOD/NO_STOCK/USER_CANCEL/OTHER',
  `reason_text` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '原因描述',
  `apply_from` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'USER/MERCHANT/PLATFORM',
  `status` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING/APPROVED/PROCESSING/SUCCEEDED/FAILED/REJECTED',
  `auditor_id` bigint unsigned DEFAULT NULL COMMENT '审核账号 id',
  `audit_note` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '审核意见',
  `audited_at` datetime(3) DEFAULT NULL,
  `channel_refund_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '渠道退款流水号',
  `succeeded_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_o_refund_no` (`refund_no`),
  KEY `idx_o_refund_order` (`order_id`,`status`),
  KEY `idx_o_refund_todo` (`status`,`created_at`),
  CONSTRAINT `fk_o_refund_order` FOREIGN KEY (`order_id`) REFERENCES `o_order` (`id`) ON DELETE CASCADE
