CREATE TABLE `p_payment` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `payment_no` char(24) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '平台支付流水号,兼渠道商户订单号',
  `order_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned NOT NULL COMMENT '冗余自订单,便于按用户排查支付问题',
  `pay_amount` int unsigned NOT NULL COMMENT '应付分',
  `channel` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MOCK' COMMENT 'MOCK/WXPAY_H5/WXPAY_JSAPI/ALIPAY_WAP/CAMPUS_CARD',
  `status` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING/PAYING/SUCCESS/FAILED/CLOSED',
  `prepay_id` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '渠道预下单标识',
  `channel_txn_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '渠道成功流水号',
  `paid_at` datetime(3) DEFAULT NULL,
  `closed_at` datetime(3) DEFAULT NULL,
  `client_ip` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'H5 下单必填',
  `fail_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '失败码',
  `fail_reason` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '失败描述',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_p_payment_no` (`payment_no`),
  KEY `idx_p_payment_order` (`order_id`,`status`),
  KEY `idx_p_payment_txn` (`channel_txn_no`),
  KEY `idx_p_payment_reconcile` (`status`,`paid_at`),
  CONSTRAINT `fk_p_payment_order` FOREIGN KEY (`order_id`) REFERENCES `o_order` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='支付流水';
